func updateDates(
    _ item: Item, expirationDate: Date?, openingDate: Date?,
    now: Date = Date(), calendar: Calendar = .current
) -> Result<Void, ActionError> {
    // rollbackで他の入力を失わないよう、モデルへ反映する前に保存境界を確認する。
    guard !context.hasChanges else {
        return .failure(.pendingChanges)
    }

    guard item.modelContext === context else {
        return .failure(.itemNotInContext)
    }

    guard let status = item.status else {
        return .failure(.validation(.unknownCurrentStatus))
    }

    let rules = ItemRules(status: status, openingDate: openingDate, consumedDate: item.consumedDate)
    switch item.updateState(using: rules, now: now, calendar: calendar) {
    case .success:
        break
    case .failure(let error):
        return .failure(.validation(error))
    }

    item.expirationDate = expirationDate

    switch save(context) {
    case .success:
        return .success(())
    case .failure(let error):
        context.rollback()
        return .failure(.persistence(error))
    }
}

// draftの日付はモデルへ事前反映せず、同じ入力をそのまま再試行できる。
try ItemActions(context: context).updateDates(
    item, expirationDate: expirationDate, openingDate: opening, now: registrationDate
).get()

#expect(!context.hasChanges)
expectEditedDates(item, expiration: expirationDate, opening: opening)
#expect(item.id == original.id)
#expect(item.statusRawValue == original.statusRawValue)
#expect(item.consumedDate == original.consumedDate)
#expect(item.product === product)
#expect(ItemSnapshot(sibling) == siblingSnapshot)
let reader = ModelContext(container)
let items = try reader.fetch(FetchDescriptor<Item>())
#expect(items.count == 2)
#expect(ItemSnapshot(try #require(items.first { $0.id == item.id })) == ItemSnapshot(item))
#expect(ItemSnapshot(try #require(items.first { $0.id == sibling.id })) == siblingSnapshot)

let rules = ItemRules(status: status, openingDate: openingDate, consumedDate: item.consumedDate)
switch item.updateState(using: rules, now: now, calendar: calendar) {
case .success:
    break
case .failure(let error):
    return .failure(.validation(error))
}

extension Item {
    /// 全検証が成功した場合だけ反映する。ModelContextの保存・保存失敗時の復旧は呼び出し側が行う。
    func updateState(
        using rules: ItemRules, now: Date, calendar: Calendar = .current
    ) -> Result<Void, ItemRules.ValidationError> {
        rules.validate(from: status, now: now, calendar: calendar).map {
            statusRawValue = rules.status.rawValue
            openingDate = rules.openingDate
            consumedDate = rules.consumedDate
            updatedAt = now
        }
    }
}
